an_ride=true,catch_threshold={1000},class="自然类精灵",description="能够生产出纺线的精灵，纺线主要由卡波体内的蛋白质和唾液构成。卡波的唾液中带有某种未知诅咒，即使是同类触碰到的话也会中毒陷入昏睡。",ecology={eggs={{description="在「铅字幻梦」赛季的代币商店内购得的珍贵精灵蛋，经过孵化可以得到“了不起”天分、且拥有量身定制资质的卡波。",fixed_aptitudes={{stat="生命",value=8},{stat="物攻",value=8},{stat="物防",value=8}},fixed_nature="固执",fixed_nature_negative="魔攻",fixed_nature_positive="物攻",icon="Item_150789.png",name="卡波的蛋"},{description="经过孵化可以得到“异色”外观、“了不起”天分的卡波。",icon="Item_150799.png",is_shiny=true,name="异色卡波的蛋"}},fruits={{description="通过观察其花纹可以看出，这是卡波的果实。",icon="Item_108102.png",name="卡波的果实",sources={"完成赛季作业挑战课题"},wisdom_tree=false}}},egg_group={7},egg_size={huge_min=1497,max=1508,min=910,mini_max=921,unit="g"},evolution_id="evolution_a834f03d489e",feature_skill_id="skill_000178",game_id=3264,gender_ratio={female=5,male=5},handbook_id="handbook_000430",handbook_show_topics=true,has_shiny=true,height="0.47~0.67M",id="pet_000220",image={egg="Item_107102.png",fruits={"Item_108102.png"},has_egg=true,has_fruit=true,head="PetAvatar_3264.png",illustration="PetPortrait_xieefangchui.png",shiny="PetPortrait_xieefangchui_yise.png"},learnset_id="learnset_94327ed0cf07",move_type="地面",name="卡波",number="430",perception_range=40,relation_key="恶系",release={date="2026-07-16",version="1.1.0"},review_gold=1200,siblings={},stage=1,starlight=24,stats={atk=65,def=66,hp=94,spa=18,spd=55,spe=68},submit_reward=1200,talent_pool_id=1001,title="卡波",types={"恶系"},weight="2.6~3.77KG"},pet_000221={can_double_ride=false,can_ride=true,catch_threshold={250},class="自然类精灵",description="据传说卡拉波斯曾经是一个仙子，因为误会诅咒过一位公主，被诅咒反噬后变为纺锤的模样。一次最多能够拉出7000米纺线。当体内的蛋白质耗尽的时候，它们就不会再进行任何活动陷入长久的昏睡中。",ecology={acquisition_pet_id="pet_000220"},egg_group={7},egg_size={huge_min=1497,max=1508,min=910,mini_max=921,unit="g"},evolution_id="evolution_a834f03d489e",feature_skill_id="skill_000178",game_id=3265,gender_ratio={female=5,male=5},handbook_id="handbook_000431",handbook_show_topics=true,has_shiny=true,height="0.83~1.19M",id="pet_000221",image={egg="Item