=6125,mini_max=6217,unit="g"},evolution_id="evolution_c8681805bf5e",feature_skill_id="skill_000083",game_id=3267,gender_ratio={female=5,male=5},handbook_id="handbook_000243",handbook_show_topics=true,has_shiny=false,height="0.83~1.19M",id="pet_000223",image={egg="Item_107103.png",fruits={"Item_108103.png"},has_egg=true,has_fruit=true,head="PetAvatar_3267.png",illustration="PetPortrait_shandianmanyu.png"},learnset_id="learnset_9c631bd35e7e",move_type="地面",name="闪电鳗鱼",number="243",perception_range=40,relation_key="电系|水系",release={date="2026-03-26",version="1.0.0"},review_gold=3000,siblings={},stage=2,starlight=60,stats={atk=115,def=104,hp=85,spa=115,spd=112,spe=115},submit_reward=3000,talent_pool_id=1001,title="闪电鳗鱼",types={"电系","水系"},weight="68.9~76.5KG"},pet_000224={can_double_ride=true,can_ride=true,catch_threshold={1000},class="自然类精灵",description="首次被人发现时，大头骨龙在地下岩层中沉睡，并且对现在的世界和精灵社会一无所知。骨架不仅坚硬，而且具有再生能力。即使骨头被打断，也可以在短时间内重新长出。骨质翅膀虽然看起来脆弱，但实际上非常坚韧。",ecology={areas={"独角兽领地","恶水沼泽","黑水峡"},fruits={{description="通过观察其花纹可以看出，这是大头骨龙的果实。",icon="Item_108104.png",name="大头骨龙的果实",sources={"完成寂灭骨龙的图鉴课题获得"},wisdom_tree=false}}},egg_group={14,2},egg_size={huge_min=13263,max=13400,min=6510,mini_max=6647,unit="g"},evolution_id="evolution_457adfa30843",feature_skill_id="skill_000129",game_id=3268,gender_ratio={female=5,male=5},handbook_id="handbook_000289",handbook_show_topics=true,has_shiny=false,height="0.85~1M",id="pet_000224",image={egg="Item_107104.png",fruits={"Item_108104.png"},has_egg=true,has_fruit=true,head="PetAvatar_3268.png",illustration="PetPortrait_datougulong.png"},learnset_id="learnset_e1c7b7e68094",move_type="步行",name="大头骨龙",number="289",perception_range=40,relation_key="龙系|幽系",release={date="2026-03-26",version="1.0.0"},review_gold=1600,siblings={},stage=1,starlight=32,stats={atk=109,def=84,hp=96,spa=40,spd=65,spe=48},submit_reward=1600,talent_pool_id=1002,title="大头骨龙",types={"龙系","幽系"},weight="18.6~33.5KG"},pet_000225={can_double_ride=true,can_ride=true,catch_thresh