egative="魔攻",fixed_nature_positive="物攻",fixed_talent="奇袭",fixed_talent_description="投掷本精灵一定可以触发背袭，包括警惕性极高的噩梦污染精灵。",icon="Item_150064.png",name="雪娃娃的蛋",sources={"雪灵的守护地"}},{description="在雪灵的守护地发现的珍贵精灵蛋，经过孵化可以得到“了不起”天分、且拥有量身定制资质、“亲密”特长的雪娃娃。",dungeon="dg_000006",fixed_aptitudes={{stat="生命",value=8},{stat="物攻",value=8},{stat="速度",value=8}},fixed_nature="固执",fixed_nature_negative="魔攻",fixed_nature_positive="物攻",fixed_talent="亲密",fixed_talent_description="更喜欢与小洛克互动，容易触发摸摸头。并且亲密度的获取效率也将大幅提升。",icon="Item_150088.png",name="雪娃娃的蛋",sources={"雪灵的守护地"}}},fruits={{description="通过观察其花纹可以看出，这是雪娃娃的果实。",icon="Item_108121.png",name="雪娃娃的果实",sources={"完成雪灵的图鉴课题获得"},wisdom_tree=false}}},egg_group={7},egg_size={huge_min=3247,max=3264,min=2380,mini_max=2397,unit="g"},evolution_id="evolution_723e7156bd7c",feature_skill_id="skill_000044",game_id=3333,gender_ratio={female=5,male=5},handbook_id="handbook_000139",handbook_show_topics=true,has_shiny=false,height="0.29~0.42M",id="pet_000272",image={egg="Item_107122.png",fruits={"Item_108121.png"},has_egg=true,has_fruit=true,head="PetAvatar_3333.png",illustration="PetPortrait_xuewawa.png"},learnset_id="learnset_738460df43e9",move_type="步行",name="雪娃娃",number="139",perception_range=40,relation_key="冰系",release={date="2026-03-26",version="1.0.0"},review_gold=1200,siblings={},stage=1,starlight=24,stats={atk=67,def=63,hp=56,spa=67,spd=63,spe=69},submit_reward=1200,talent_pool_id=1001,title="雪娃娃",types={"冰系"},weight="6.8~8.16KG"},pet_000273={can_double_ride=false,can_ride=true,catch_threshold={250,500},class="自然类精灵",description="缔结契约的向往更明显，甚至会主动靠近潜在契约者，似乎由冰元素和某种尚不清楚的物质构成，推测该物质来自强烈的信念与精神力，使它们的契约更稳定、也更难被外力改变。",ecology={acquisition_pet_id="pet_000272",areas={"星霜崖地","岚语峰西侧","巨人裂谷南","巨人裂谷北"}},egg_group={7},egg_size={huge_min=3247,max=3264,min=2380,mini_max=2397,unit="g"},evolution_id="evolution_723e7156bd7c",feature_skill_id="skill_000044",game_id=3334,gender_ratio={female=5,male=5},handbook_id="handbook_000140",handbook_show_topics=true,has_shiny=false,hei