ide=true,can_ride=true,class="自然类精灵",description="和普通的鸟精灵看起来差不多，小小的，连叫声都不怎么响亮，只是独自站在崖石上，每天扑扇几下翅膀，比昨天多飞出一点点距离。 “走自己最平凡的路，按照自己的意志行动，追逐自己最真实的梦想”。",egg_group={1},evolution_id="evolution_94ad4c253b70",feature_skill_id="skill_000048",game_id=3392,gender_ratio={female=5,male=5},handbook_id="handbook_000351",handbook_show_topics=true,has_shiny=false,height="0.35~0.5M",id="pet_000314",image={egg="Item_107136.png",has_egg=true,has_fruit=false,head="PetAvatar_3392.png",illustration="PetPortrait_fanque.png"},learnset_id="learnset_177e9d0aff6d",move_type="步行",name="凡雀",number="351",perception_range=40,relation_key="翼系",release={date="2026-05-21",version="1.0.1"},siblings={},stage=1,stats={atk=55,def=52,hp=71,spa=53,spd=66,spe=75},submit_reward=4000,talent_pool_id=1002,title="凡雀",types={"翼系"},weight="3.08~6KG"},pet_000315={can_double_ride=true,can_ride=true,class="自然类精灵",description="安静独立的精灵，在长期在高空迎风飞行后，翅膀尖端开始显出橘色的翎羽，它们一天一天地练习，一根羽毛一根羽毛地蜕变，翼系研究员管这个过程叫\"凡羽蜕金\"。",egg_group={1},evolution_id="evolution_94ad4c253b70",feature_skill_id="skill_000048",game_id=3393,gender_ratio={female=5,male=5},handbook_id="handbook_000352",handbook_show_topics=true,has_shiny=false,height="0.65~0.85M",id="pet_000315",image={has_egg=false,has_fruit=false,head="PetAvatar_3393.png",illustration="PetPortrait_zilingying.png"},learnset_id="learnset_177e9d0aff6d",move_type="步行",name="紫翎鹰",number="352",perception_range=40,relation_key="翼系",release={date="2026-05-21",version="1.0.1"},siblings={},stage=2,stats={atk=74,def=69,hp=94,spa=71,spd=88,spe=100},submit_reward=4000,talent_pool_id=1002,title="紫翎鹰",types={"翼系"},weight="13.04~20.5KG"},pet_000316={can_double_ride=true,can_ride=true,catch_threshold={1000},class="自然类精灵",description="身形变成了梭形，修长的尾羽薄而宽，能把横着吹来的山风悄悄转成向上的托力。研究院测过它的风阻系数，低得离谱，但凡鹰自己好像并不在意这些数据。它飞得很稳，不快不慢，从平凡到非凡，它从没停过，也从没急过。",egg_group={1},evolution_id="evolution_94ad4c253b70",feature_skill_id="skill_000048",game_id=3394,gender_ratio={female=5,male=5},handbook_id="handbook_000353",handbook_show_topics=true,h