6-03-26",version="1.0.0"},siblings={},stage=2,stats={atk=87,def=102,hp=105,spa=87,spd=66,spe=100},submit_reward=4000,talent_pool_id=1002,title="灵羽勇士",types={"翼系"},weight="11.5~14.2KG"},pet_000319={can_double_ride=true,can_ride=true,class="自然类精灵",description="庇佑这片纯粹的净土，是拥有强大力量之后背负的使命。从上古壁画中得知尘封的过往，它寻求力量，发自内心地想要保护现在的一切。“张开圣洁的羽翼，为同伴抵挡风雨，便是它心中的圣歌。”",egg_group={1},evolution_id="evolution_55e03a78ba18",feature_skill_id="skill_000113",game_id=3397,gender_ratio={female=5,male=5},handbook_id="handbook_000152",handbook_show_topics=true,has_shiny=false,height="2.1~2.55M",id="pet_000319",image={fruits={"Item_108136.png"},has_egg=false,has_fruit=true,head="PetAvatar_3397.png",illustration="PetPortrait_shengyuyiwang.png"},learnset_id="learnset_ddb62523ae7b",move_type="步行",name="圣羽翼王",number="152",perception_range=40,relation_key="翼系",release={date="2026-03-26",version="1.0.0"},siblings={},stage=3,stats={atk=109,def=128,hp=132,spa=109,spd=83,spe=125},submit_reward=4000,talent_pool_id=1002,title="圣羽翼王",types={"翼系"},weight="195~296KG"},pet_000320={can_double_ride=true,can_ride=true,catch_threshold={1000},class="自然类精灵",description="洛克与精灵开始缔结契约的时候诞生的物种。以精灵契约为食，是极其稀少的物种。囫囵吞下咕噜球后，先整个保存在身体里一段时间，非常久之后才能完全消化掉。虽然也能吃其他食物，但很难从中获取养分。",egg_group={4},egg_size={huge_min=339,max=340,min=263,mini_max=264,unit="g"},evolution_id="evolution_8d612806ba02",feature_skill_id="skill_000056",game_id=3398,gender_ratio={female=5,male=5},handbook_id="handbook_000317",handbook_show_topics=true,has_shiny=false,height="0.15~0.2M",id="pet_000320",image={egg="Item_107138.png",fruits={"Item_108137.png"},has_egg=true,has_fruit=true,head="PetAvatar_3398.png",illustration="PetPortrait_xingchenchong.png"},learnset_id="learnset_78db2061204f",move_type="地面",name="星尘虫",number="317",perception_range=40,relation_key="虫系",release={date="2026-03-26",version="1.0.0"},review_gold=1600,siblings={},stage=1,starlight=32,stats={atk=47,def=46,hp=49,spa=47,spd=58,spe=60},submit_reward=1600,talent_pool_id=1002,title="星尘虫",types={"虫系"},weight="0.45~1.4KG"},pet_000321={can_double_ride=true,can_ride=true,catch_threshold={500},class="自然类精灵",description="与精灵缔结契约的形式发生变化，咕噜球的样子世代更替，这一种族的外表也渐渐发生了变化。有人曾经尝试使用特殊咕噜球喂食，虫的形态在数年后发生变化，但实验没有继续下来，猜测是因为资金不足。",egg_group={4},egg_size={huge_min=339,max=340,min=263,mini_max=264,unit="g"},evolution_id="evolution_8d612806ba02",feature_skill_id="skill_000056",game_id=3399,gender_ratio={female=5,male=5},handbook_id="handbook_000318",handbook_show_topics=true,has_shiny=false,height="0.35~0.4M",id="pet_000321",image={egg="Item_107138.png",fruits={"Item_108137.png"},has_egg=true,has_fruit=true,head="PetAvatar_3399.png",illustration="PetPortrait_luoxingchong.png"},learnset_id="learnset_78db2061204f",move_type="地面",name="落星虫",number="318",perception_range=40,relation_key="虫系",release={date="2026-03-26",version="1.0.0"},review_gold=2800,siblings={},stage=2,starlight=56,stats={atk=62,def=61,hp=65,spa=62,spd=77,spe=80},submit_reward=2800,talent_pool_id=1002,title="落星虫",types={"虫系"},weight="1.25~2.25KG"},pet_000322={can_double_ride=true,can_ride=true,catch_threshold={250},class="自然类精灵",description="在这个虫族中存在着森严的等级制度，某些虫有资格吃到更稀有的咕噜球。咕噜球研究科曾经提出过一个实验课题《陨星虫与国王球的对撞实验》，后来课题被取消了，原因不明。",egg_group={4},egg_size={huge_min=339,max=340,min=263,mini_max=264,unit="g"},evolution_id="evolution_8d612806ba02",feature_skill_id="skill_000056",game_id=3400,gender_ratio={female=5,male=5},handbook_id="handbook_000319",handbook_show_topics=true,has_shiny=false,height="0.65~0.8M",id="pet_000322",image={egg="Item_107138.png",fruits={"Item_108137.png"},has_egg=true,has_fruit=true,head="PetAvatar_3400.png",illustration="PetPortrait_yunxingchong.png"},learnset_id="learnset_78db2061204f",move_type="地面",name="陨星虫",number="319",perception_range=40,relation_key="虫系",release={date="2026-03-26",version="1.0.0"},review_gold=4000,siblings={},stage=3,starlight=80,stats={atk=78,def=76,hp=81,spa=78,spd=96,spe=100},submit_reward=4000,talent_pool_id=1002,title="陨星虫",types={"虫系"},weight="5.6~6.8KG"},pet_000323={can_double_ride=true,can_ride=true,catch_threshold={1000},class="自然类精灵",description="钳子其实还很脆弱，夹不碎太硬的东西。尾巴尖上粘着几块它从地底矿脉上敲下来的水晶，这可是非常厉害的成果，它见谁都举着尾巴，以此显示自己厉害。",ecology={areas={"巨人裂谷北"},eggs={{description="在碎晶蝎的守护地发现的珍贵精灵蛋，经过孵化可以得到“了不起”天分、且拥有量身定制资质、“灵巧”特长的碎晶蝎。",dungeon="dg_000030",fixed_aptitudes={{stat="生命",value=8},{stat="物攻",value=8},{stat="魔防",value=8}},fixed_nature="固执",fixed_nature_negative="魔攻",fixed_nature_positive="物攻",fixed_talent="灵巧",fixed_talent_description="本精灵的采集范围更大。",icon="Item_150094.png",name="碎晶蝎的蛋",sources={"碎晶蝎的守护地"}}},fruits={{description="通过观察其花纹可以看出，这是碎晶蝎的果实。",icon="Item_108139.png",name="碎晶蝎的果实",sources={"完成碎晶蝎的图鉴课题获得"},wisdom_tree=false}}},egg_group={4,11},egg_size={huge_min=5750,max=5800,min=3262,mini_max=3312,unit="g"},evolution_id="evolution_ea91c92bedee",feature_skill_id="skill_000180",game_id=3402,gender_ratio={female=5,male=5},handbook_id="handbook_000381",handbook_show_topics=true,has_shiny=false,height="0.4~0.54M",id="pet_000323",image={egg="Item_107140.png",fruits={"Item_108139.png"},has_egg=true,has_fruit=true,head="PetAvatar_3402.png",illustration="PetPortrait_suijingxie.png"},learnset_id="learnset_48da798fb635",move_type="地面",name="碎晶蝎",number="381",perception_range=40,relation_key="恶系|地系",release={date="2026-07-16",version="1.1.0"},review_gold=1200,siblings={},stage=1,starlight=24,stats={atk=76,def=71,hp=65,spa=70,spd=47,spe=57},submit_reward=1200,talent_pool_id=1002,title="碎晶蝎",types={"恶系","地系"},weight="9.32~14.5KG"},pet_000324={can_double_ride=true,can_ride=true,catch_threshold={500},class="自然类精灵",description="不停锤炼自己，以获得更强的力量。它开始主动挑战占据优质矿脉的对手，被它占领过的矿脉上都留着深深的钳痕，就像是它们的签名。",ecology={acquisition_pet_id="pet_000323",areas={"巨人裂谷北"}},egg_group={4,11},egg_size={huge_min=5750,max=5800,min=3262,mini_max=3312,unit="g"},evolution_id="evolution_ea91c92bedee",feature_skill_id="skill_000180",game_id=3403,gender_ratio={female=5,male=5},handbook_id="handbook_000382",handbook_show_topics=true,has_shiny=false,height="0.48~0.59M",id="pet_000324",image={egg="Item