="Item_107025.png",fruits={"Item_108025.png"},has_egg=true,has_fruit=true,head="PetAvatar_3055.png",illustration="PetPortrait_banbanke_tuipi.png"},learnset_id="learnset_d30bc0b122ac",move_type="步行",name="板板壳",number="012",perception_range=40,relation_key="水系",release={date="2026-03-26",version="1.0.0"},review_gold=800,siblings={"pet_000047"},stage=1,starlight=16,stats={atk=24,def=56,hp=88,spa=72,spd=59,spe=48},submit_reward=800,talent_pool_id=1002,title="板板壳（蜕皮时的样子）",types={"水系"},weight="6.8~9.5KG"},pet_000410={affinity={enjoy={"火系","水系"}},can_double_ride=true,can_ride=true,catch_threshold={500},class="自然类精灵",description="很少再缩进壳里，即使遇到危险也会勇敢面对。甲壳内一部分是空气，一部分是水，通过喷嘴来调节重量从而在水中下潜和上浮。",ecology={acquisition_pet_id="pet_000409",areas={"圣羽祭台","金水河谷","仪式镇"}},egg_group={3},egg_size={huge_min=4169,max=4200,min=2625,mini_max=2656,unit="g"},evolution_id="evolution_5de4d985f1e1",feature_skill_id="skill_000031",form="蜕皮时的样子",game_id=3517,gender_ratio={female=5,male=5},handbook_id="handbook_000013",has_shiny=false,height="0.65~0.92M",id="pet_000410",image={egg="Item_107025.png",fruits={"Item_108025.png"},has_egg=true,has_fruit=true,head="PetAvatar_3056.png",illustration="PetPortrait_kakake_tuipi.png"},learnset_id="learnset_d30bc0b122ac",move_type="步行",name="咔咔壳",number="013",perception_range=40,relation_key="水系",release={date="2026-03-26",version="1.0.0"},review_gold=1400,siblings={"pet_000048"},stage=2,starlight=28,stats={atk=31,def=75,hp=117,spa=96,spd=79,spe=64},submit_reward=1400,talent_pool_id=1002,title="咔咔壳（蜕皮时的样子）",types={"水系"},weight="17.5~22.5KG"},pet_000411={affinity={enjoy={"火系","水系"}},can_double_ride=true,can_ride=true,catch_threshold={250},class="自然类精灵",description="进化之后体重增长到原来的数倍，前肢的力量也变得十分发达。前面有坚硬的尖角，背后有甲壳和水炮的泵口，是像堡垒一样可靠的存在。",ecology={acquisition_pet_id="pet_000409",areas={"圣羽祭台","金水河谷"}},egg_group={3},egg_size={huge_min=4169,max=4200,min=2625,mini_max=2656,unit="g"},evolution_id="evolution_5de4d985f1e1",feature_skill_id="skill_000031",form="蜕皮时的样子",game_id=3518,gend