e=false,can_ride=true,catch_threshold={1000,50000},class="自然类精灵",description="和噜噜家族是远亲，但几乎从不联系，即使是同种族的斑斑们互相之间也并不亲近。从蛋里孵出来之后就非常独立了，经常迈着毛茸茸的小腿，挥着小小的翅膀巡视领地，十分高傲。",ecology={areas={"圣所前哨","回填山涧","港口驻地","二叠山丘","监管区","望风半岛"},eggs={{description="在斑枭的守护地发现的珍贵精灵蛋，经过孵化可以得到“了不起”天分、且拥有量身定制资质、“疾行”特长的斑斑。",dungeon="dg_000023",fixed_aptitudes={{stat="生命",value=8},{stat="物攻",value=8},{stat="物防",value=8}},fixed_nature="固执",fixed_nature_negative="魔攻",fixed_nature_positive="物攻",fixed_talent="疾行",fixed_talent_description="骑乘时移动速度将略微提升； 若恰逢精灵偏爱的地形或天气，还可获得移动增益。",icon="Item_150082.png",name="斑斑的蛋",sources={"斑枭的守护地"}},{description="经过孵化可以得到“异色”外观、“了不起”天分的斑斑。",icon="Item_150803.png",is_shiny=true,name="异色斑斑的蛋"},{description="参与活动「斑斑大量出没」获得的珍贵精灵蛋，经过孵化可以得到“炫彩”外观、“了不起”天分的斑斑。",icon="Item_151032.png",name="斑斑的蛋",sources={"参与活动「斑斑大量出没」"}}},fruits={{description="通过观察其花纹可以看出，这是斑斑的果实。",icon="Item_108173.png",name="斑斑的果实",sources={"完成斑枭的图鉴课题获得"},wisdom_tree=false}}},egg_group={5},egg_size={huge_min=2453,max=2468,min=1677,mini_max=1692,unit="g"},evolution_id="evolution_d57d0a559b19",feature_skill_id="skill_000131",game_id=3534,gender_ratio={female=5,male=5},handbook_id="handbook_000177",handbook_show_topics=true,has_shiny=true,height="0.47~0.6M",id="pet_000421",image={egg="Item_107188.png",fruits={"Item_108173.png"},has_egg=true,has_fruit=true,head="PetAvatar_3534.png",illustration="PetPortrait_banban.png",shiny="PetPortrait_banban_yise.png"},learnset_id="learnset_9c5714da2924",move_type="步行",name="斑斑",number="177",perception_range=40,relation_key="翼系",release={date="2026-03-26",version="1.0.0"},review_gold=800,siblings={},stage=1,starlight=16,stats={atk=90,def=82,hp=87,spa=90,spd=91,spe=92},submit_reward=800,talent_pool_id=1001,title="斑斑",types={"翼系"},weight="4.79~6.17KG"},pet_000422={can_double_ride=false,can_ride=true,catch_threshold={500,50000},class="自然类精灵",description="和洛克相交甚少的种族，拥有比较强的野性和攻击性。如果在领地内看到生面孔，可能俯冲下来攻击对方，拥有出色的深度感知能力和夜视能力，即使藏在阴影处也难以逃过它的双眼。",ecology={acquisition_pet_id="pet_000421",areas=