="圣剑-X",types={"机械系"},weight="481~658KG"},pet_000431={can_double_ride=true,can_ride=true,catch_threshold={500},class="自然类精灵",description="在机械系精灵中非常有声望。曾经制造出帕帕斯卡的洛克许下一个愿望，希望能让机械系精灵有尊严地活着。于是帕帕斯卡整个种族一直在想办法让机械系精灵过上更体面更开心的生活。",ecology={acquisition_pet_id="pet_000384",areas={"沉船漩涡","拾荒港口","淘晶镇"}},egg_group={15,5},egg_size={huge_min=1720,max=1740,min=728,mini_max=748,unit="g"},evolution_id="evolution_59bcfb16063d",feature_skill_id="skill_000132",game_id=3547,gender_ratio={female=5,male=5},handbook_id="handbook_000262",handbook_show_topics=true,has_shiny=false,height="1.05~1.47M",id="pet_000431",image={egg="Item_107178.png",fruits={"Item_108165.png"},has_egg=true,has_fruit=true,head="PetAvatar_3547.png",illustration="PetPortrait_papasika.png"},learnset_id="learnset_98f7c8a6ea33",move_type="步行",name="帕帕斯卡",number="262",perception_range=40,relation_key="机械系|翼系",release={date="2026-03-26",version="1.0.0"},review_gold=2100,siblings={},stage=2,starlight=42,stats={atk=68,def=99,hp=110,spa=10,spd=84,spe=100},submit_reward=2100,talent_pool_id=1002,title="帕帕斯卡",types={"机械系","翼系"},weight="48.7~60.1KG"},pet_000432={can_double_ride=true,can_ride=true,catch_threshold={1000},class="自然类精灵",description="“黄金时代地系部族大多无法运用魔力，但他们有着独特的智慧和精湛的技艺。地系精灵王教他们使用建造之术，地系部族用黑色矿物做出了棋子精灵，用以娱乐”——《黄金时代的地系工匠们·二》",ecology={areas={"银蛇河口","王国城堡","二叠山丘"},eggs={{description="击败精灵首领·棋契陛下后，发现的珍贵精灵蛋，通过观察其花纹可以获得一些头绪，经过孵化可以得到“了不起”天分的精灵。",icon="Item_150522.png",name="棋棋的蛋",sources={"精灵首领·棋契陛下掉落"}},{description="击败精灵首领·棋契陛下后，发现的珍贵精灵蛋，通过观察其花纹可以获得一些头绪，经过孵化可以得到“相当好”天分的精灵。",icon="Item_150622.png",name="棋棋的蛋",sources={"精灵首领·棋契陛下掉落"}}},fruits={{description="通过观察其花纹可以看出，这是棋棋的果实。",icon="Item_108177.png",name="棋棋的果实",sources={"完成棋骑士的图鉴课题获得"},wisdom_tree=false}}},egg_group={7},egg_size={huge_min=5759,max=5800,min=3745,mini_max=3786,unit="g"},evolution_id="evolution_f28cc1f0218e",feature_skill_id="skill_000164",form="白子",game_id=3550,gender_ratio={female=5,male=5},handbook_id="handbook_000188",handbook_show_topics=true,has_shiny=false,height="0.35~0.47M",id="pet_000432",image={egg="Item_107193.png",fruits={"Item_108177.png"},has_egg=true,has_fruit=true,head="PetAvatar_3550.png",illustration="PetPortrait_qiqi.png"},learnset_id="learnset_0d4583a51f7a",move_type="步行",name="棋棋",number="188",perception_range=40,relation_key="武系|地系",release={date="2026-03-26",version="1.0.0"},review_gold=800,siblings={"pet_000437"},stage=1,starlight=16,stats={atk=100,def=70,hp=72,spa=36,spd=56,spe=100},submit_reward=800,talent_pool_id=1002,title="棋棋（白子）",types={"武系","地系"},weight="10.7~14.5KG"},pet_000433={can_double_ride=true,can_ride=true,catch_threshold={250},class="自然类精灵",description="“棋棋的祖先们曾与地系族人相伴而生，地系部族周围多蛮兽。白天棋棋们陷入沉睡，被当作孩子的玩具，在聚落里四处滚动。夜晚则遵循着古老的指令，纷纷醒来守护着部族，替人们守夜巡逻”——《黄金时代的地系工匠们·三》",ecology={acquisition_pet_id="pet_000432",areas={"王国城堡","二叠山丘"}},egg_group={7},egg_size={huge_min=5759,max=5800,min=3745,mini_max=3786,unit="g"},evolution_id="evolution_f9b10d964cc9",feature_skill_id="skill_000164",form="白子",game_id=3551,gender_ratio={female=0,male=10},handbook_id="handbook_000189",handbook_show_topics=true,has_shiny=false,height="0.98~1.35M",id="pet_000433",image={egg="Item_107193.png",fruits={"Item_108177.png"},has_egg=true,has_fruit=true,head="PetAvatar_3551.png",illustration="PetPortrait_qiqishi.png"},learnset_id="learnset_3276b25281f8",move_type="步行",name="棋骑士",number="189",perception_range=40,relation_key="武系|地系",release={date="2026-03-26",version="1.0.0"},review_gold=2000,siblings={"pet_000438","pet_000556","pet_000576"},stage=2,starlight=40,stats={atk=126,def=88,hp=90,spa=45,spd=69,spe=125},submit_reward=2000,talent_pool_id=1002,title="棋骑士（白子）",types={"武系","地系"},weight="43.06~60.09KG"},pet_000434={can_double_ride=true,can_ride=true,catch_threshold={250},class="自然类精灵",description="“最初只有黑色棋子，后来地系工匠意外发现了光之水晶，打造了白色的棋子。黑白子交替轮班，互不相见，却共同守护地系部族。它们换班对峙时，不同棋子有各自的行走规则，逐渐发展成象棋游戏规则的雏形”——《黄金时代的地系工匠们·四》",ecology={acquisition_pet_id="pet_000432",areas={"王国城堡"}},egg_group={7},egg_size={huge_min=5759,max=5800,min=3745,mini_max=3786,unit="g"},evolution_id="evolution_5d4cd7122023",feature_skill_id="skill_000114",form="白子",game_id=3552,gender_ratio={female=10,male=0},handbook_id="handbook_000192",handbook_show_topics=true,has_shiny=false,height="1.66~1.81M",id="pet_000434",image={egg="Item_107193.png",has_egg=true,has_fruit=false,head="PetAvatar_3552.png",illustration="PetPortrait_qiqihou.png"},learnset_id="learnset_b62d50929930",move_type="步行",name="棋绮后",number="192",perception_range=40,relation_key="武系|地系",release={date="2026-03-26",version="1.0.0"},review_gold=2000,siblings={"pet_000439","pet_000573","pet_000577"},stage=2,starlight=40,stats={atk=84,def=82,hp=93,spa=84,spd=75,spe=90},submit_reward=2000,talent_pool_id=1002,title="棋绮后（白子）",types={"武系","地系"},weight="30.01~41.02KG"},pet_000435={can_double_ride=true,can_ride=true,catch_threshold={250},class="自然类精灵",description="“黑白棋子们有类似铠甲一样的外形，民间传闻中白银骑士团的盔甲就是模仿它们建造的，但也有另外一种说法是地系部族的族人参与了白银骑士团的盔甲制造，真实性都已不可考”——《黄金时代的地系工匠们·五》",ecology={acquisition_pet_id="pet_000432",areas={"银蛇河口"}},egg_group={7},egg_size={huge_min=5759,max=5800,min=3745,mini_max=3786,unit="g"},evolution_id="evolution_82baca9096dd",feature_skill_id="skill_000165",form="白子",game_id=3553,gender_ratio={female=0,male=10},handbook_id="handbook_000190",handbook_show_topics=true,has_shiny=false,height="1.45~1.71M",id="pet_000435",image={egg="Item_107193.png",has_egg=true,has_fruit=false,head="PetAvatar_3553.png",illustration="PetPortrait_qiqilei.png"},learnset_id="learnset_dde72fdf745a",move_type="步行",name="棋齐垒",number="190",perception_range=40,relation_key="武系|地系",release={date="2026-03-26",version="1.0.0"},review_gold=2000,siblings={"pet_000440","pet_000574","pet_000578"},stage=2,starlight=40,stats={atk=94,def=116,hp=89,spa=38,spd=77,spe=75},submit_reward=2000,talent_pool_id=1002,title="棋齐垒（白子）",types={"武系","地系"},weight="58.01~70.05KG"},pet_000436={can_double_ride=true,can_ride=true,catch_threshold={250},class="自然类精灵",description="“黄金时代过去后，棋棋开始了流浪，保护族人的遗痕行为一直在影响着它们，它们会主动寻找人文聚落，试图融入洛克的社会。也有部分出现在野外，这些野生的棋棋手感不如家养棋棋温润，干巴巴的有些粗糙”——《黄金时代的地系工匠们·八》",ecology={acquisition_pet_id="pet_000432",areas={"银蛇河口"}},egg_group={7},egg_size={huge_min=5759,max=5800,min=3745,mini_max=3786,unit="g"},evolution_id="evolution_840a77b84850",feature_skill_id="skill_000166",form="白子",game_id=3554,gender_ratio={female=0,male=10},handbook_id="handbook_000191",handbook_show_topics=true,has_shiny=false,height="0.98~1.35M",id="pet_000436",image={egg="Item_107193.png",has_egg=true,has_fruit=false,head="PetAvatar_3554.png",illustration="PetPortrait_qiqidu.png"},learnset_id="learnset_9340ab38ae95",move_type="步行",name="棋祈督",number="191",perception_range=40,relation_key="武系|地系",release={date="2026-03-26",version="1.0.0"},review_gold=2000,siblings={"pet_000441","pet_000575","pet_000579"},stage=2,starlight=40,stats={atk=87,def=90,hp=126,spa=87,spd=72,spe=85},submit_reward=2000,talent_pool_id=1002,title="棋祈督（白子）",types={"武系","地系"},weight="38.07~47.05KG"},pet_000437={can_double_ride=true,can_ride=true,catch_threshold={1000},class="自然类精灵",description="“从黄金时代至今，黑色棋子在月光下仍呈现乌金般幽深的纹路，它们存在本身就是黄金时代工艺的证明。传言每当乌云遮月，所有黑子便会同时转向月亮的方向，据研究可能和守夜指令有关。”——《黄金时代的地系工匠们·九》",ecology={areas={"二叠山丘"},eggs={{description="击败精灵首领·棋契陛下后，发现的珍贵精灵蛋，通过观察其花纹可以获得一些头绪，经过孵化可以得到“了不起”天分的精灵。",icon="Item_150523.png",name="棋棋的蛋",sources={"精灵首领·棋契陛下掉落"}},{description="击败精灵首领·棋契陛下后，发现的珍贵精灵蛋，通过观察其花纹可以获得一些头绪，经过孵化可以得到“相当好”天分的精灵。",icon="Item_150623.png",name="棋棋的蛋",sources={"精灵首领·棋契陛下掉落"}}},fruits={{description="通过观察其花纹可以看出，这是棋棋的果实。",icon="Item_108177.png",name="棋棋的果实",sources={"完成棋骑士的图鉴课题获得"},wisdom_tree=false}}},egg_group={7},egg_size={huge_min=5759,max=5800,min=3745,mini_max=3786,unit="g"},evolution_id="evolution_a5b0e6d8cc44",feature_skill_id="skill_000134",form="黑子",game_id=3555,gender_ratio={female=5,male=5},handbook_id="handbook_000188",has_shiny=false,height="0.35~0.47M",id="pet_000437",image={egg="Item_107194.png",fruits={"Item_108177.png"},has_egg=true,has_fruit=true,head="PetAvatar_3555.png",illustration="PetPortrait_qiqi_yidi.png"},learnset_id="learnset_cde7bdab0574",move_type="步行",name="棋棋",number="188",perception_range=40,relation_key="武系|地系",release={date="2026-03-26",version="1.0.0"},review_gold=800,siblings={"pet_000432"},stage=1,starlight=16,stats={atk=97,def=67,hp=66,spa=35,spd=53,spe=100},submit_reward=800,talent_pool_id=1002,title="棋棋（黑子）",types={"武系","地系"},weight="10.7~14.5KG"},pet_000438={can_double_ride=true,can_ride=true,catch_threshold={250},class="自然类精灵",description="“在深夜，黑色棋子会跟在洛克身后排着队列，跟着移动。因此，在民间有洛克传言，深夜千万别碰黑色棋子，它们会把影子吃掉。实际上，那只是它们守护族人的本能而已。”——《黄金时代的地系工匠们·十》",ecology={acquisition_pet_id="pet_000437",areas={"二叠山丘"}},egg_group={7},egg_size={huge_min=5759,max=5800,min=3745,mini_max=3786,unit="g"},evolution_id="evolution_44a27d3632b6",feature_skill_id="skill_000134",form="黑子",game_id=3556,gender_ratio={female=0,male=10},handbook_id="handbook_000189",has_shiny=false,height="0.98~1.35M",id="pet_000438",image={egg="Item_107194.png",fruits={"Item_108177.png"},has_egg=true,has_fruit=true,head="PetAvatar_3556.png",illustration="PetPortrait_qiqishi_yidi.png"},learnset_id="learnset_1a8d2ac1b270",move_type="步行",name="棋骑士",number="189",perception_range=40,relation_key="武系|地系",release={date="2026-03-26",version="1.0.0"},review_gold=2000,siblings={"pet_000433","pet_000556","pet_000576"},stage=2,starlight=40,stats={atk=121,def=84,hp=83,spa=43,spd=66,spe=125},submit_reward=2000,talent_pool_id=1002,title="棋骑士（黑子）",types={"武系","地系"},weight="43.06~60.09KG"},pet_000439={can_double_ride=true,can_ride=true,catch_threshold={250},class="自然类精灵",description="“黄金时代崩解后不知多久，黑子开始失眠。它们不再在日出时准点沉睡，而是继续在废土上继续巡逻。没有族人可守，它们便去围着倒塌的遗迹转圈，被认为是一种刻板行为。”——《黄金时代的地系工匠们·十三》",ecology={acquisition_pet_id="pet_000437",areas={"二叠山丘"}},egg_group={7},egg_size={huge_min=5759,max=5800,min=3745,mini_max=3786,unit="g"},evolution_id="evolution_a57e0145a38a",feature_skill_id="skill_000114",form="黑子",game_id=3557,gender_ratio={female=10,male=0},handbook_id="handbook_000192",has_shiny=false,height="1.66~1.81M",id="pet_000439",ima