4,def=63,hp=116,spa=151,spd=127,spe=110},submit_reward=2100,talent_pool_id=1001,title="音碟吼",types={"普通系","机械系"},weight="23.1~40.8KG"},pet_000508={can_double_ride=true,can_ride=true,class="自然类精灵",description="被洛克制造并赋予美好的使命，它们的底层结构里面写着“去吧，去给孩子们带来快乐吧。”于是它们年复一年日复一日，用不太灵光的脑袋想，用有点笨的小手做，尝试制作出所有能让洛克感觉到快乐的事物。",ecology={eggs={{description="完成「狂欢怪谈」赛季作业获得的珍贵精灵蛋，经过孵化可以得到“完美无瑕”，且拥有量身定制资质的钨丝贝贝。",fixed_aptitudes={{stat="生命",value=10},{stat="物攻",value=10},{stat="魔防",value=10}},fixed_nature="固执",fixed_nature_negative="魔攻",fixed_nature_positive="物攻",icon="Item_150746.png",name="钨丝贝贝的蛋",sources={"完成「狂欢怪谈」赛季作业"}}}},egg_group={1},evolution_id="evolution_fa68f67b18f7",feature_skill_id="skill_000168",game_id=3733,gender_ratio={female=5,male=5},handbook_id="handbook_000348",handbook_show_topics=true,has_shiny=false,height="0.54~0.73M",id="pet_000508",image={egg="Item_150746.png",has_egg=true,has_fruit=false,head="PetAvatar_3733.png",illustration="PetPortrait_wusibeibei.png"},learnset_id="learnset_09ce6e70eec5",move_type="地面",name="钨丝贝贝",number="348",perception_range=40,relation_key="机械系",release={date="2026-05-21",version="1.0.1"},siblings={},stage=1,stats={atk=68,def=78,hp=62,spa=63,spd=54,spe=33},submit_reward=4000,talent_pool_id=1002,title="钨丝贝贝",types={"机械系"},weight="9.7~14.8KG"},pet_000509={can_double_ride=true,can_ride=true,class="自然类精灵",description="经常对着空气练习，有洛克靠近时会立刻启动表演程序。有时显得笨拙不够善解人意，如果小洛克曾因为它的笑话而微笑，它可以不眠不休追着小洛克讲三天三夜的笑话，然后直接昏倒。",ecology={acquisition_pet_id="pet_000508"},egg_group={1},evolution_id="evolution_fa68f67b18f7",feature_skill_id="skill_000168",game_id=3734,gender_ratio={female=5,male=5},handbook_id="handbook_000349",handbook_show_topics=true,has_shiny=false,height="1.03~1.41M",id="pet_000509",image={has_egg=false,has_fruit=false,head="PetAvatar_3734.png",illustration="PetPortrait_huiguangmuji.png"},learnset_id="learnset_09ce6e70eec5",move_type="地面",name="辉光幕机",number="349",perception_range=40,relation_key="机械系",release={date="2026-05-21",version="1.0.1"},siblings={},stag