{atk=106,def=119,hp=96,spa=106,spd=93,spe=115},submit_reward=3000,title="高帽鹬者",types={"翼系"},weight="35~50KG"},pet_000588={affinity={enjoy={"幽系"},hate={"光系"}},can_double_ride=false,can_ride=true,class="漂浮类精灵",description="统领所有恶魔叮和叮叮恶魔，幼年时害怕失去注意力的特质进化成了强烈的支配欲，它的领地内不允许有比它更显眼的存在。继承了族群重视诺言的传统，一旦认定效忠对象就绝不背叛，但它的忠诚只给被它认可的主人。",ecology={acquisition_pet_id="pet_000009",areas={"奥贝斯坦湖","圣羽祭台","挽风屏障","风眠圣所","独角兽领地","恶水沼泽","黑水峡","晨曦山","月兔暗港","威廉古堡","迷雾之森","淘晶镇"}},egg_group={7},egg_size={huge_min=1633,max=1640,min=1260,mini_max=1267,unit="g"},evolution_id="evolution_d19004f02b9b",feature_skill_id="skill_000239",form="首领形态",game_id=5055,gender_ratio={female=5,male=5},handbook_id="handbook_000031",has_shiny=true,height="1.35~1.6M",id="pet_000588",image={egg="Item_107007.png",fruits={"Item_108007.png"},has_egg=true,has_fruit=true,head="PetAvatar_4105.png",illustration="PetPortrait_anyingemo.png",shiny="PetPortrait_anyingemo_yise.png"},is_lord_evolution=true,learnset_id="learnset_86ca6b50c925",move_type="地面",name="恶魔男爵",number="031",perception_range=40,relation_key="恶系|翼系",release={date="2026-07-16",version="1.1.0"},siblings={"pet_000036"},stage=4,stats={atk=128,def=103,hp=117,spa=55,spd=73,spe=120},submit_reward=2000,title="恶魔男爵",types={"恶系","翼系"},weight="40~60KG"},pet_000589={can_double_ride=false,can_ride=true,class="自然类精灵",description="活了足够久的风滚暮虫，叶片会逐渐失去所有色素，变得像风干的白纸。它们有着最高的拟态造诣，身体极轻极薄，落地没有声响，没有任何精灵会对一片“枯死的叶子”产生警觉。",ecology={acquisition_pet_id="pet_000303"},egg_group={4,8},egg_size={huge_min=100,max=100,min=53,mini_max=53,unit="g"},evolution_id="evolution_65fad33ff121",feature_skill_id="skill_000241",form="金黄的样子",game_id=5056,gender_ratio={female=5,male=5},handbook_id="handbook_000120",has_shiny=false,height="0.98~1.25M",id="pet_000589",image={egg="Item_107130.png",has_egg=true,has_fruit=false,head="PetAvatar_4101.png",illustration="PetPortrait_fenggunmuchong_shouling.png"},is_lord_evolution=true,learnset_id="learnset_71757e7458a6",move_type="地面",name="暮风隐者",number="120",perception