stats={atk=98,def=116,hp=98,spa=97,spd=84,spe=120},title="测风蝉",types={"翼系","机械系"},weight="9.9~17KG"},pet_000606={can_double_ride=true,can_ride=true,class="自然类精灵",description="迷雾森林曾经的原住民，如今已在卡洛西亚大陆几乎绝迹。胸口嵌着一颗黄色宝石，据说封着一股来历不明的力量。它们沉默寡言，独自穿行于林间的雾气之中，遇到别的精灵便远远绕开，一整个白天都说不上一句话。",ecology={eggs={{description="完成「月涌狂想」赛季作业获得的珍贵精灵蛋，经过孵化可以得到“完美无瑕”，且支持自选性格与个体资质、拥有“无畏”特长的诅咒狼灵。",icon="Item_150831.png",name="诅咒狼灵的蛋",sources={"完成「月涌狂想」赛季作业"}}}},egg_group={1},evolution_id="evolution_0ed502614ad1",feature_skill_id="skill_000196",game_id=3761,handbook_id="handbook_000443",handbook_show_topics=true,has_shiny=false,height="0.59~0.84M",id="pet_000606",image={egg="Item_150831.png",has_egg=true,has_fruit=false,head="PetAvatar_3759.png",illustration="PetPortrait_img_Wus_LangLing1_001_Res.png"},learnset_id="learnset_162b16b43e43",move_type="地面",name="诅咒狼灵",number="443",perception_range=40,relation_key="幽系|幻系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=1,stats={atk=77,def=77,hp=69,spa=31,spd=59,spe=78},submit_reward=3000,talent_pool_id=1001,title="诅咒狼灵",types={"幽系","幻系"},weight="8.5~13.3KG"},pet_000607={can_double_ride=true,can_ride=true,class="自然类精灵",description="在有月亮的夜里，光芒会顺着它们胸前毛发的边缘缓缓流淌。它开始学会踏着月光潜行，落地几乎无声。仍是独来独往，很少与其他精灵哪怕是同族并肩行动，即便在同一片林子里遇见，也只是遥遥对望一眼便各自离开。",ecology={acquisition_pet_id="pet_000606"},egg_group={1},evolution_id="evolution_0ed502614ad1",feature_skill_id="skill_000196",game_id=3762,handbook_id="handbook_000444",handbook_show_topics=true,has_shiny=false,height="1.35~1.66M",id="pet_000607",image={has_egg=false,has_fruit=false,head="PetAvatar_3762.png",illustration="PetPortrait_img_Wus_LangLing2_001_Res.png"},learnset_id="learnset_162b16b43e43",move_type="地面",name="新月狼灵",number="444",perception_range=40,relation_key="幽系|幻系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=2,stats={atk=103,def=102,hp=92,spa=41,spd=78,spe=104},submit_reward=3000,talent_pool_id=1001,title="新月狼灵",types={"幽系","幻系"},weight="30.5~47KG"},pet_000608={can_double_ride=true,can_ride=true,class="自然类精灵",description="独自行走的离群之狼，月缺时它力量最弱，只是安静地趴在某块山石上休息。月圆那一夜，它会从月光最亮的地方走出来。当你看见银月狼王的时候，它已经看了你很久了，如果挥手打招呼的话，它也只是远远的点头致意。",ecology={acquisition_pet_id="pet_000606"},egg_group={1},evolution_id="evolution_0ed502614ad1",feature_skill_id="skill_000196",game_id=3763,handbook_id="handbook_000445",handbook_show_topics=true,has_shiny=false,height="1.73~2.05M",id="pet_000608",image={has_egg=false,has_fruit=false,head="PetAvatar_3763.png",illustration="PetPortrait_img_Wus_LangLing3_001_Res.png"},learnset_id="learnset_162b16b43e43",move_type="地面",name="银月狼王",number="445",perception_range=40,relation_key="幽系|幻系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=3,stats={atk=128,def=128,hp=115,spa=51,spd=98,spe=130},submit_reward=3000,talent_pool_id=1001,title="银月狼王",types={"幽系","幻系"},weight="77~115KG"},pet_000609={can_double_ride=true,can_ride=true,catch_threshold={1000},class="自然类精灵",description="月光下很难看到新月鹭，它们会融入月光在水面的倒影里，啄水里的月光。月亮躲进云里时，才发现岸边一直站着一只缩着脖子的新月鹭，好像刚才什么都没发生。",ecology={eggs={{description="购买「月涌通行证-月之华」闪耀契约礼券获得的珍贵精灵蛋，经过孵化可以得到“异色”外观、“了不起”天分、且支持自选性格、个体资质的新月鹭。",icon="Item_150812.png",is_shiny=true,name="异色新月鹭的蛋",sources={"购买「月涌通行证-月之华」闪耀契约礼券"}}},fruits={{description="通过观察其花纹可以看出，这是新月鹭的果实。",icon="Item_108202.png",name="新月鹭的果实",sources={"月涌通行证获得"},wisdom_tree=false}}},egg_group={1},evolution_id="evolution_3d0cc5393c1a",feature_skill_id="skill_000198",game_id=3764,handbook_id="handbook_000446",handbook_show_topics=true,has_shiny=true,height="0.46~0.6M",id="pet_000609",image={egg="Item_149247.png",fruits={"Item_108202.png"},has_egg=true,has_fruit=true,head="PetAvatar_3764.png",illustration="PetPortrait_img_Win_XinYueLu1_001_Res.png",shiny="PetPortrait_img_Win_XinYueLu1_101_Res.png"},learnset_id="learnset_da630e35c0e9",move_type="地面",name="新月鹭",number="446",perception_range=40,relation_key="翼系|冰系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=1,stats={atk=59,def=62,hp=50,spa=60,spd=68,spe=69},submit_reward=3000,talent_pool_id=1001,title="新月鹭",types={"翼系","冰系"},weight="3.7~5KG"},pet_000610={can_double_ride=true,can_ride=true,catch_threshold={500},class="自然类精灵",description="月辉鹭蹲在水面的月亮倒影上，一动不动，就像在孵月亮。有的洛克相信月亮发光不是因为月亮自己会发光，是因为有月辉鹭蹲着把光芒传输给月亮，也有洛克持相反态度。",ecology={acquisition_pet_id="pet_000609"},egg_group={1},evolution_id="evolution_3d0cc5393c1a",feature_skill_id="skill_000198",game_id=3765,handbook_id="handbook_000447",handbook_show_topics=true,has_shiny=true,height="0.82~1.13M",id="pet_000610",image={has_egg=false,has_fruit=false,head="PetAvatar_3765.png",illustration="PetPortrait_img_Win_XinYueLu2_001_Res.png",shiny="PetPortrait_img_Win_XinYueLu2_101_Res.png"},learnset_id="learnset_da630e35c0e9",move_type="地面",name="月辉鹭",number="447",perception_range=40,relation_key="翼系|冰系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=2,stats={atk=79,def=83,hp=66,spa=80,spd=90,spe=92},submit_reward=3000,talent_pool_id=1001,title="月辉鹭",types={"翼系","冰系"},weight="6.83~9.7KG"},pet_000611={can_double_ride=true,can_ride=true,catch_threshold={250},class="自然类精灵",description="月使鹭纳出没的地方，天上的月亮只剩一道细弧。月光全在它们身上，它们是这片湖区最亮的夜晚光源。等到它们换羽的日子，羽毛上的月光会跟着脱落，洒回天上，月亮又会重新变圆。",ecology={acquisition_pet_id="pet_000609"},egg_group={1},evolution_id="evolution_3d0cc5393c1a",feature_skill_id="skill_000198",game_id=3766,handbook_id="handbook_000448",handbook_show_topics=true,has_shiny=true,height="1.71~1.94M",id="pet_000611",image={has_egg=false,has_fruit=false,head="PetAvatar_3766.png",illustration="PetPortrait_img_Win_XinYueLu3_001_Res.png",shiny="PetPortrait_img_Win_XinYueLu3_101_Res.png"},learnset_id="learnset_da630e35c0e9",move_type="地面",name="月使鹭纳",number="448",perception_range=40,relation_key="翼系|冰系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=3,stats={atk=99,def=104,hp=83,spa=100,spd=113,spe=115},submit_reward=3000,talent_pool_id=1001,title="月使鹭纳",types={"翼系","冰系"},weight="41~75.8KG"},pet_000612={can_double_ride=false,can_ride=true,catch_threshold={1000},class="自然类精灵",description="章脑丸思考的时候，半透明的身体里会有一小串光顺着神经一节一节亮过去，它们总是成群漂在近岸的浅水里，小脑袋一起明明灭灭，那是它们在聊天。",ecology={eggs={{description="在「月涌狂想」赛季的代币商店内购得的珍贵精灵蛋，经过孵化可以得到“完美无瑕”、且支持自选性格与个体资质的章脑丸。",icon="Item_150836.png",name="章脑丸的蛋"},{description="经过孵化可以得到“异色”外观、“了不起”天分的章脑丸。",icon="Item_150853.png",is_shiny=true,name="异色章脑丸的蛋"}},fruits={{description="通过观察其花纹可以看出，这是章脑丸的果实。",icon="Item_108205.png",name="章脑丸的果实",sources={"完成赛季作业挑战课题"},wisdom_tree=false}}},egg_group={7,10},egg_size={huge_min=1246,max=1260,min=525,mini_max=539,unit="g"},evolution_id="evolution_b13349d01c38",feature_skill_id="skill_000200",game_id=3767,handbook_id="handbook_000452",handbook_show_topics=true,has_shiny=true,height="0.59~0.9M",id="pet_000612",image={egg="Item_107245.png",fruits={"Item_108205.png"},has_egg=true,has_fruit=true,head="PetAvatar_3767.png",illustration="PetPortrait_img_Lig_ZhangNaoWan1_001_Res.png",shiny="PetPortrait_img_Lig_ZhangNaoWan1_101_Res.png"},learnset_id="learnset_1828f13f54f1",move_type="地面",name="章脑丸",number="452",perception_range=40,relation_key="光系|水系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=1,stats={atk=42,def=69,hp=89,spa=99,spd=99,spe=80},submit_reward=3000,talent_pool_id=1001,title="章脑丸",types={"光系","水系"},weight="1.5~3.15KG"},pet_000613={can_double_ride=false,can_ride=true,catch_threshold={250},class="自然类精灵",description="极聪明的精灵，无数光点从四周向智辉章脑汇聚，又从它这里散回四周，族群里所有的所见所感，最终都汇入它的脑中。它们偏爱有洛克生活的水域，能理解洛克说话的语气。",ecology={acquisition_pet_id="pet_000612",activities={{name="命定花种",note="花种出没·战斗后可捕捉",window="2026-09-10 ~ 2026-09-25"}},destined_flower={nature="胆小"}},egg_group={7,10},egg_size={huge_min=1246,max=1260,min=525,mini_max=539,unit="g"},evolution_id="evolution_b13349d01c38",feature_skill_id="skill_000200",game_id=3768,handbook_id="handbook_000453",handbook_show_topics=true,has_shiny=true,height="1.53~1.7M",id="pet_000613",image={egg="Item_107245.png",fruits={"Item_108205.png"},has_egg=true,has_fruit=true,head="PetAvatar_3768.png",illustration="PetPortrait_img_Lig_ZhangNaoWan3_001_Res.png",shiny="PetPortrait_img_Lig_Zha