{"幽系"},weight="0.95~2KG"},pet_000617={can_double_ride=true,can_ride=true,catch_threshold={250},class="自然类精灵",description="成长后恶作剧也升了级，它会招呼一群幽铃埋伏在旧宅子的各个角落，等洛克推门进来，就四处发出声音，把洛克吵得团团转，自己却都不露面。被吓的洛克若是不生气，它们便会觉得有点没意思，悻悻地散去。",ecology={acquisition_pet_id="pet_000616"},egg_group={7,12},egg_size={huge_min=791,max=800,min=332,mini_max=341,unit="g"},evolution_id="evolution_bacfc388de61",feature_skill_id="skill_000204",game_id=3774,handbook_id="handbook_000462",handbook_show_topics=true,has_shiny=true,height="1.05~1.37M",id="pet_000617",image={egg="Item_107247.png",fruits={"Item_108221.png"},has_egg=true,has_fruit=true,head="PetAvatar_3774.png",illustration="PetPortrait_img_Gho_YouLing3_001_Res.png",shiny="PetPortrait_img_Gho_YouLing3_101_Res.png"},learnset_id="learnset_76a86cb172ea",move_type="地面",name="摇铃魔偶",number="462",perception_range=40,relation_key="幽系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=2,stats={atk=46,def=99,hp=123,spa=117,spd=131,spe=95},submit_reward=3000,talent_pool_id=1001,title="摇铃魔偶",types={"幽系"},weight="4.73~8.9KG"},pet_000618={can_double_ride=false,can_ride=true,catch_threshold={1000},class="自然类精灵",description="布灵的样子是一只手工缝的小熊，真正的它其实是从熊头顶露出来的那一小团黄色能量，布偶只是它给自己找的一个不那么显眼的壳。据说它的家乡是一片被黑暗吃掉过的星空，所以它到现在都怕黑。",ecology={eggs={{description="在「月涌狂想」赛季的代币商店内购得的珍贵精灵蛋，经过孵化可以得到“完美无瑕”、且支持自选性格与个体资质的布灵。",icon="Item_150839.png",name="布灵的蛋"},{description="经过孵化可以得到“异色”外观、“了不起”天分的布灵。",icon="Item_150856.png",is_shiny=true,name="异色布灵的蛋"}},fruits={{description="通过观察其花纹可以看出，这是布灵的果实。",icon="Item_108241.png",name="布灵的果实",sources={"完成赛季作业挑战课题"},wisdom_tree=false}}},egg_group={7},egg_size={huge_min=1144,max=1160,min=350,mini_max=366,unit="g"},evolution_id="evolution_16cfea3594a0",feature_skill_id="skill_000207",game_id=3775,handbook_id="handbook_000464",handbook_show_topics=true,has_shiny=true,height="0.38~0.51M",id="pet_000618",image={egg="Item_107248.png",fruits={"Item_108241.png"},has_egg=true,has_fruit=true,head="PetAvatar_3775.png",illustration="PetPortrait_img_Ill